package com.bank.gc;

import java.math.BigDecimal;

// Two LedgerNodes referencing each other as prev/next form an ISLAND:
// they point at each other, but once no external root reaches them,
// the whole pair is collectable despite the mutual references.
public class LedgerNode {
    private final String txnId;
    private final BigDecimal amount;
    private LedgerNode prev;
    private LedgerNode next;

    public LedgerNode(String txnId, BigDecimal amount) {
        this.txnId = txnId;
        this.amount = amount;
    }

    public void linkTo(LedgerNode other) {
        this.next = other;   // this → other
        other.prev = this;   // other → this  (mutual reference = island when orphaned)
    }

    public String getTxnId() { return txnId; }
    public BigDecimal getAmount() { return amount; }
}
