package com.bank.gc;

import java.lang.ref.WeakReference;
import java.math.BigDecimal;
import java.util.logging.*;

public class GcEligibilityDemo {
    private static final Logger log = Logger.getLogger(GcEligibilityDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        // A normal transfer first.
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        BigDecimal rentAmount = new BigDecimal("50000");
        rajesh.debit(rentAmount);
        priya.credit(rentAmount);
        log.info(() -> "Transfer " + rentAmount + " SUCCESS, Rajesh=" + rajesh.getBalance()
                + " Priya=" + priya.getBalance());

        // PATH 1 — nulling the only reference makes an object eligible.
        Account temp = new Account("TMP0001", "Temp", new BigDecimal("1"));
        WeakReference<Account> watch1 = new WeakReference<>(temp);
        temp = null; // last strong reference gone → eligible
        hintGcAndReport("PATH 1 (nulled reference)", watch1);

        // PATH 2 — a scoped temporary goes out of scope when the helper returns.
        WeakReference<Account> watch2 = createScopedTemp();
        hintGcAndReport("PATH 2 (out of scope)", watch2);

        // PATH 3 — island of isolation: two nodes referencing each other, head dropped.
        LedgerNode head = new LedgerNode("TXN100", new BigDecimal("50000"));
        LedgerNode tail = new LedgerNode("TXN101", new BigDecimal("20000"));
        head.linkTo(tail); // head↔tail mutual references
        WeakReference<LedgerNode> watchHead = new WeakReference<>(head);
        WeakReference<LedgerNode> watchTail = new WeakReference<>(tail);
        head = null; tail = null; // no external root reaches the pair → island eligible
        hintGcAndReport("PATH 3 head (island)", watchHead);
        hintGcAndReport("PATH 3 tail (island)", watchTail);
    }

    // The temp Account exists only inside this method; when it returns, the local
    // goes out of scope and the Account loses its last root path.
    private static WeakReference<Account> createScopedTemp() {
        Account scoped = new Account("SCOPED1", "Scoped", new BigDecimal("5"));
        return new WeakReference<>(scoped); // weak ref does NOT keep it alive
    }

    private static void hintGcAndReport(String label, WeakReference<?> ref) throws InterruptedException {
        System.gc();          // only a HINT; eligibility does not mean instant collection
        Thread.sleep(50);
        boolean collected = (ref.get() == null);
        log.info(() -> label + " → collected? " + collected);
    }
}
